-- =============================================================================
-- Catálogo — importação dos RESGUARDOS (GME) da MUDELAR (Excel do utilizador Resguardos.xlsx, folha «Folha1»).
-- Base de RH (uetjghdkwbywbftedtth). Ficheiro GERADO por script (gerar.js + parse.js) a partir do Excel: as linhas de
-- dados abaixo não se editam à mão — regeneram-se. Molde: 20270118400000 (bases de duche, muitos produtos, set-based) e
-- 20270119000000 (atributo de lista criado se faltar).
-- =============================================================================
--
-- Decisões do utilizador (17/11):
--   * «Duche & Banho» › «Resguardos de Duche», marca GME, fornecedor Anlorbel = o que já existe
--     («ANLORBEL COMERCIO MATERIAIS CONSTRUCAO E DECORACAO»; o nome do Excel vem com os acentos estragados).
--   * Nome: «Resguardo Resguardo …» passa a «Resguardo …»; o resto fica como vem (o espanhol também).
--   * Produto = modelo + atributos. Modelo = o nome sem «Resguardo», sem a medida, o acabamento e a cor (e sem as
--     marcas de extração «AMBIGUO»/«Genérico»); a composição entre parênteses («(20+60)», «(145+145)») NÃO é medida e
--     fica no nome — e por isso no modelo (ver «Por decidir» no relatório: sem ela há 260 colisões).
--   * Medida: um número → Largura (lista; opção «100», sigla 100); 70x70 → Medida 2D; «95-100» → Largura com a opção de
--     lista «95-100» (a Medida exige duas dimensões); «85 (82,5-85)» → Largura «82,5-85» (o 85 é o nome comercial);
--     «83,5-85,5/48,5-50,5» → Medida 2D com dois intervalos {de, ate} (20270119600000); «22.5/25» → Largura «22,5-25»;
--     «até 40cm» → Largura «0-40». Decimais com vírgula no texto da opção.
--   * Sigla da opção de Largura: o número («100»), ou <de>A<ate> com P no lugar da vírgula («95A100», «22P5A25»).
--     A sigla tem no máximo 6 caracteres (attribute_option_group_values_sigla_check): quando não cabe, a sigla é
--     <de>A<ate> sem as décimas («66A68» para 66,5-68), depois os mesmos algarismos sem o A («106108» para 106,5-108),
--     depois as décimas por extenso sem separador («665695» para 66,5-69,5), depois o início com a décima e os dois
--     últimos algarismos do fim («102505» para 102,5-105, decisão de 17/11: nada de siglas automáticas que parecem
--     larguras). Se mesmo assim nenhuma couber ou estiverem todas ocupadas, para (RAISE) em vez de inventar uma sigla.
--   * DBRS0845CR/NG e DBRS0845CR-2/NG-2 têm o mesmo nome no Excel («Perfil Acessorio») mas são produtos diferentes
--     (decisão de 17/11): o nome real vem da Descrição — «Perfil de pared Open» (25 €) e «Perfil cierre iman» (60 €) —
--     no modelo e no nome do produto. Os DBRS0840 «-2» continuam de fora.
--   * Acabamento: atributo NOVO de lista («acabamento»), opções «Transparente» (TR) e «Frost Plus» (FP). Só leva o
--     atributo quem tem Frost Plus (no nome, ou nos XX na coluna «Codigo do Fornecedor»): 397 produtos. Não há
--     colisão entre um Frost Plus e o seu equivalente transparente (o SKU difere no -FP).
--   * Cor no fim do nome: Cromo → CROMO, Negro → NEGRO, Oro → ORO, Blanco → Branco, Niquel → NIQUEL, Titanio → TITANIO,
--     Cobre → Cobre (as opções que a Mudelar já tem; criadas se faltarem, com sigla livre). XX, AMBIGUO e Genérico no
--     fim: sem cor.
--   * Pares «-2»: os que só diferem nas peças do fornecedor ficam só com o primeiro (nenhum código do «-2» se guarda).
--   * Os 11 «não rotulado» ficam de fora. Ao todo ficam de fora 20 das 2561 linhas; entram 2541.
--   * Sem preço (288 rascunhos): entram com « (sem preço)» no fim do nome e sem product_prices; a ligação ao
--     fornecedor fica sem preço.
--   * Preços: custo = «Preço Compra» arredondado a 2 casas, PVP = «Preço Venda», IVA 23. Grossista/distribuidor = 0:
--     não se gravam. Estado = o do Excel (active / draft).
--   * supplier_sku = «Codigo do Fornecedor» (a composição de peças, ex. «6530C+6561»); sem código (ou com «Transparente»
--     / «Frost Plus» nessa coluna, nos XX) = o SKU novo.
--   * SKU = regra do Catálogo: DB-RD-NNNN-<cor>-<medida 2D>-<largura>-<acabamento> (pela sku_ordem da Mudelar); NNNN =
--     o número do modelo, pela ordem da primeira linha de cada modelo no Excel. O SKU antigo não se guarda.
--
-- Como em 20270118400000: SET-BASED, com o SKU calculado antes de inserir (a regra de fn_cat_sku_partes) e conferido
-- depois com fn_cat_sku_partes + fn_cat_modelo_numero para TODOS e com cat_prever_sku_modelo para 20 ao acaso. Os INSERT em
-- massa (products, product_organizations, product_prices, product_attribute_values, item_suppliers) correm com
-- app.audit_bypass = 'on'; fica UMA linha consolidada na auditoria. As escritas pequenas (opções, atributo, modelos)
-- ficam auditadas normalmente. Fonte: app.audit_source = 'migration:resguardos_mudelar'.
--
-- Idempotente com as outras importações (aplicadas por ordem): atributos, opções, marca, fornecedor e modelos procuram-se
-- primeiro pelo nome/código (fn_cat_chave_opcao) e reutilizam-se.
--
-- GUARDA (inerte: RAISE NOTICE e sai sem escrever nada) se: a organização 3242e925-… não existir com o nome 'Mudelar';
-- faltar a versão dos modelos (20270118300000); não existirem «Duche & Banho» › «Resguardos de Duche»; a subcategoria já
-- tiver produtos (vivos ou apagados); já houver um produto vivo da Mudelar com um dos nomes; ou já houver na
-- subcategoria um modelo com um dos nomes ou números que não seja exatamente o mesmo. Inerte numa segunda execução.
-- Falha (RAISE EXCEPTION, nada fica) se faltar o resto: o intervalo na medida (20270119600000), siglas da categoria e da
-- subcategoria, marca GME, fornecedor Anlorbel, atributos cor/medida, uma opção ambígua ou desativada, membro para
-- created_by, SKU repetido (diz quais) ou já usado noutro produto da Mudelar.
--
-- Conferir no fim (conta o que está ERRADO e faz RAISE se não for 0): 2541 produtos, por modelo, 558 modelos;
-- cada produto como a sua linha (nome, SKU, modelo, marca, estado, fornecedor, preços, atributos e só esses); SKUs únicos,
-- no formato, iguais ao recalculado (todos) e a cat_prever_sku_modelo (20); o atributo Acabamento; as siglas da Largura;
-- nada escrito fora da Mudelar (xmin) nem noutros produtos dela; uma amostra de SKUs de outras categorias intacta.
--
-- ORDEM: depois de 20270119600000 (intervalo na medida). Teste: supabase/tests/catalogo_resguardos_mudelar.test.sql
-- (BEGIN … ROLLBACK, só leitura; o passo 0 falha antes). ATENÇÃO antes do db push: `supabase db push` aplica TUDO o que
-- estiver pendente; listar com `supabase migration list --linked` imediatamente antes.
-- =============================================================================

SET lock_timeout = '5s';
SET statement_timeout = '15min';

DO $mig$
DECLARE
  c_org         constant uuid    := '3242e925-da26-459a-8258-be04d904e355';
  c_fonte       constant text    := 'migration:resguardos_mudelar';
  c_total       constant integer := 2541;
  c_n_modelos   constant integer := 558;
  c_n_com_preco constant integer := 2253;
  c_n_valores   constant integer := 5421;
  c_n_frost     constant integer := 397;
  c_n_larguras  constant integer := 259;
  c_n_medidas   constant integer := 136;
  c_iva         constant numeric := 23;
  c_cat_nome    constant text    := 'Duche & Banho';
  c_sub_nome    constant text    := 'Resguardos de Duche';
  c_marca_nome  constant text    := 'GME';
  c_forn_nome   constant text    := 'ANLORBEL COMERCIO MATERIAIS CONSTRUCAO E DECORACAO';
  c_unidade     constant text    := 'un';
  c_acab_nome   constant text    := 'Acabamento';
  c_larg_nome   constant text    := 'Largura';
  c_frost       constant text    := 'Frost Plus';
  c_transp      constant text    := 'Transparente';
  c_amostra     constant integer := 20;
  c_max_modelos_ativos constant integer := 2000;
  c_max_modelos_vivos  constant integer := 10000;
  c_max_atributos      constant integer := 200;
  v_agora   timestamptz := clock_timestamp();
  v_n bigint; v_m bigint; v_k bigint; v_i integer; v_ordem integer; v_xid text; v_txt text; v_code text;
  v_cat uuid; v_sub uuid; v_cat_sigla text; v_sub_sigla text; v_cat_ativa boolean; v_sub_ativa boolean;
  v_marca uuid; v_ativa boolean; v_uom uuid; v_sup uuid; v_sup_nome text; v_criador uuid;
  v_a_cor uuid; v_a_med uuid; v_a_larg uuid; v_a_acab uuid; v_g_cor uuid; v_g_larg uuid; v_g_acab uuid; v_med_unit text;
  v_larg_criado boolean := false; v_acab_criado boolean := false; v_frost uuid; v_frost_valor text; v_frost_sigla text;
  v_opc uuid; v_prefixo text; v_regex text; v_cores_criadas text := ''; v_siglas text;
  v_auth uuid; v_claims text; v_prev jsonb; v_attrs jsonb; r record;
BEGIN
  -- ─── 0. Guarda (inerte) ───────────────────────────────────────────────────────
  IF NOT EXISTS (SELECT 1 FROM anew_organizations o WHERE o.id = c_org AND o.name = 'Mudelar' AND o.deleted_at IS NULL) THEN
    RAISE NOTICE 'resguardos_mudelar: a organização Mudelar (%) não existe nesta base — nada a fazer.', c_org;
    RETURN;
  END IF;
  IF to_regclass('public.product_models') IS NULL
     OR to_regprocedure('public.fn_cat_modelo_numero(uuid,uuid,uuid)') IS NULL
     OR to_regprocedure('public.cat_prever_sku_modelo(uuid,uuid,uuid,uuid,jsonb,uuid)') IS NULL
     OR to_regprocedure('public.cat_gerar_sku_produto(uuid,uuid,boolean)') IS NULL
     OR position('fn_cat_modelo_numero' IN coalesce((SELECT pr.prosrc FROM pg_proc pr
                                                     WHERE pr.oid = to_regprocedure('public.cat_gerar_sku_produto(uuid,uuid,boolean)')::oid), '')) = 0 THEN
    RAISE NOTICE 'resguardos_mudelar: falta a versão dos modelos (20270118300000) — nada a fazer.';
    RETURN;
  END IF;
  -- as funções do Catálogo que esta importação usa (existem na RH: se faltarem, é erro, não guarda)
  SELECT string_agg(s, ', ') INTO v_txt
  FROM unnest(ARRAY['public.fn_cat_chave_opcao(text)', 'public.fn_cat_limpar_nome(text)',
                    'public.fn_cat_grupo_do_atributo(uuid,uuid)', 'public.fn_cat_medida_ler(jsonb,text)',
                    'public.fn_cat_sku_medida(jsonb)', 'public.fn_cat_sku_partes(uuid,uuid,uuid,jsonb)',
                    'public.fn_cat_sigla_opcao_livre(uuid,text,uuid)', 'public.fn_cat_unidade(uuid,text)',
                    'public.fn_cat_dimensao_medida(jsonb,text)', 'public.fn_cat_dimensao_texto(jsonb)',
                    'public.has_anew_permission_in_org(uuid,text,uuid)',
                    'public.fn_manual_audit_log(text,uuid,uuid,text,jsonb,text,uuid)']) s
  WHERE to_regprocedure(s) IS NULL;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'resguardos_mudelar: faltam funções do Catálogo (%).', v_txt; END IF;
  -- a medida com intervalo (20270119600000) tem de estar aplicada: há Medidas 2D com dois intervalos
  IF public.fn_cat_sku_medida('{"tipo":"2D","largura":{"de":83.5,"ate":85.5},"comprimento":{"de":48.5,"ate":50.5},"unidade":"cm"}'::jsonb)
       IS DISTINCT FROM '83P5A85P5X48P5A50P5' THEN
    RAISE EXCEPTION 'resguardos_mudelar: a medida ainda não aceita intervalos (aplicar 20270119600000 antes).';
  END IF;

  -- categoria e subcategoria
  SELECT count(*), (array_agg(c.id ORDER BY c.created_at, c.id))[1], (array_agg(c.sigla ORDER BY c.created_at, c.id))[1],
         (array_agg(coalesce(c.is_active, true) ORDER BY c.created_at, c.id))[1]
    INTO v_n, v_cat, v_cat_sigla, v_cat_ativa
  FROM product_categories c
  WHERE c.organization_id = c_org AND c.parent_id IS NULL AND c.deleted_at IS NULL
    AND public.fn_cat_chave_opcao(c.name) = public.fn_cat_chave_opcao(c_cat_nome);
  IF v_n = 0 THEN
    RAISE NOTICE 'resguardos_mudelar: a Mudelar não tem a categoria «%» — nada a fazer.', c_cat_nome;
    RETURN;
  ELSIF v_n > 1 THEN
    RAISE EXCEPTION 'resguardos_mudelar: há % categorias «%» na Mudelar.', v_n, c_cat_nome;
  END IF;
  SELECT count(*), (array_agg(c.id ORDER BY c.created_at, c.id))[1], (array_agg(c.sigla ORDER BY c.created_at, c.id))[1],
         (array_agg(coalesce(c.is_active, true) ORDER BY c.created_at, c.id))[1]
    INTO v_n, v_sub, v_sub_sigla, v_sub_ativa
  FROM product_categories c
  WHERE c.organization_id = c_org AND c.parent_id = v_cat AND c.deleted_at IS NULL
    AND public.fn_cat_chave_opcao(c.name) = public.fn_cat_chave_opcao(c_sub_nome);
  IF v_n = 0 THEN
    RAISE NOTICE 'resguardos_mudelar: a Mudelar não tem a subcategoria «%» › «%» — nada a fazer.', c_cat_nome, c_sub_nome;
    RETURN;
  ELSIF v_n > 1 THEN
    RAISE EXCEPTION 'resguardos_mudelar: há % subcategorias «%» em «%».', v_n, c_sub_nome, c_cat_nome;
  END IF;
  -- produtos na subcategoria (vivos ou apagados: um apagado guarda o SKU) → inerte
  SELECT count(*) INTO v_n FROM products p WHERE p.organization_id = c_org AND p.subcategory_id = v_sub;
  IF v_n > 0 THEN
    RAISE NOTICE 'resguardos_mudelar: a subcategoria «%» da Mudelar já tem % produtos — nada a fazer.', c_sub_nome, v_n;
    RETURN;
  END IF;

  -- ─── Os dados do Excel (gerados) ──────────────────────────────────────────────
  DROP TABLE IF EXISTS pg_temp._rsg_modelos, pg_temp._rsg_larguras, pg_temp._rsg_medidas, pg_temp._rsg_cores,
                       pg_temp._rsg_linhas, pg_temp._rsg_attr, pg_temp._rsg_amostra, pg_temp._rsg;

  -- os modelos: número (NNNN do SKU, pela ordem da primeira linha no Excel), nome, quantos produtos
  CREATE TEMP TABLE _rsg_modelos (numero smallint PRIMARY KEY, nome text NOT NULL, esperados integer NOT NULL, modelo_id uuid) ON COMMIT DROP;
  INSERT INTO _rsg_modelos (numero, nome, esperados) VALUES
