  -- os dados gerados estão inteiros
  SELECT count(*), count(DISTINCT l.nome), count(*) FILTER (WHERE l.frost), count(*) FILTER (WHERE l.custo IS NOT NULL)
    INTO v_n, v_m, v_k, v_i
  FROM _rsg_linhas l;
  IF v_n <> c_total OR v_m <> c_total OR v_k <> c_n_frost OR v_i <> c_n_com_preco THEN
    RAISE EXCEPTION 'resguardos_mudelar: os dados gerados têm % linhas (% nomes, % Frost Plus, % com preço) em vez de % (%, %, %).',
      v_n, v_m, v_k, v_i, c_total, c_total, c_n_frost, c_n_com_preco;
  END IF;
  IF (SELECT count(*) FROM _rsg_modelos) <> c_n_modelos OR (SELECT sum(m.esperados) FROM _rsg_modelos m) <> c_total
     OR (SELECT count(*) FROM _rsg_larguras) <> c_n_larguras OR (SELECT count(*) FROM _rsg_medidas) <> c_n_medidas
     OR (SELECT count(DISTINCT public.fn_cat_chave_opcao(m.nome)) FROM _rsg_modelos m) <> c_n_modelos THEN
    RAISE EXCEPTION 'resguardos_mudelar: os modelos, larguras ou medidas gerados não batem (ou há nomes de modelo repetidos).';
  END IF;
  IF EXISTS (SELECT 1 FROM _rsg_linhas l
             WHERE NOT EXISTS (SELECT 1 FROM _rsg_modelos m WHERE m.numero = l.modelo)
                OR (l.cor IS NOT NULL AND NOT EXISTS (SELECT 1 FROM _rsg_cores c WHERE c.nome_excel = l.cor))
                OR (l.largura IS NOT NULL AND NOT EXISTS (SELECT 1 FROM _rsg_larguras x WHERE x.valor = l.largura))
                OR (l.medida IS NOT NULL AND NOT EXISTS (SELECT 1 FROM _rsg_medidas d WHERE d.id = l.medida))
                OR (l.largura IS NOT NULL AND l.medida IS NOT NULL)
                OR l.status NOT IN ('active', 'draft')
                OR (l.custo IS NULL) <> (l.pvp IS NULL) OR l.custo <= 0 OR l.pvp <= 0
                OR (l.custo IS NULL AND l.nome NOT LIKE '% (sem preço)') OR (l.custo IS NOT NULL AND l.nome LIKE '% (sem preço)')
                OR l.nome !~ '^Resguardo ' OR l.nome ~ '^Resguardo Resguardo ') THEN
    RAISE EXCEPTION 'resguardos_mudelar: há linhas com modelo, cor, medida, estado, preço ou nome fora do esperado.';
  END IF;
  -- produto = modelo + atributos: nenhuma combinação repetida (senão o SKU repetia)
  SELECT string_agg(x.k, '; ') INTO v_txt FROM (
    SELECT l.modelo || '/' || coalesce(l.cor, '-') || '/' || coalesce(l.largura, '-') || '/' || coalesce(l.medida::text, '-') || '/' || l.frost::text AS k
    FROM _rsg_linhas l GROUP BY l.modelo, l.cor, l.largura, l.medida, l.frost HAVING count(*) > 1 LIMIT 10) x;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'resguardos_mudelar: combinações repetidas (modelo/cor/largura/medida/frost): %', v_txt; END IF;

  -- mais guardas inertes: os nomes já existem na Mudelar? modelos com o mesmo nome/número que não sejam estes?
  SELECT count(*) INTO v_n FROM products p
  WHERE p.organization_id = c_org AND NOT p.is_deleted AND p.name IN (SELECT l.nome FROM _rsg_linhas l);
  IF v_n > 0 THEN
    RAISE NOTICE 'resguardos_mudelar: a Mudelar já tem % produtos vivos com nomes do Excel — nada a fazer.', v_n;
    RETURN;
  END IF;
  SELECT string_agg(pm.name || ' (' || lpad(pm.numero::text, 4, '0') || (CASE WHEN pm.deleted_at IS NOT NULL THEN ', apagado' ELSE '' END) || ')', ', ')
    INTO v_txt
  FROM product_models pm
  WHERE pm.organization_id = c_org AND pm.subcategory_id = v_sub
    AND EXISTS (SELECT 1 FROM _rsg_modelos m
                WHERE (pm.numero = m.numero OR (pm.deleted_at IS NULL AND public.fn_cat_chave_opcao(pm.name) = public.fn_cat_chave_opcao(m.nome)))
                  AND NOT (pm.numero = m.numero AND pm.deleted_at IS NULL AND public.fn_cat_chave_opcao(pm.name) = public.fn_cat_chave_opcao(m.nome)));
  IF v_txt IS NOT NULL THEN
    RAISE NOTICE 'resguardos_mudelar: a subcategoria já tem modelos com estes nomes ou números, diferentes dos do Excel (%) — nada a fazer.', left(v_txt, 1500);
    RETURN;
  END IF;

  -- ─── Configuração que tem de existir (senão: erro) ───────────────────────────
  IF v_cat_sigla IS NULL OR v_sub_sigla IS NULL THEN
    RAISE EXCEPTION 'resguardos_mudelar: «%» ou «%» não têm sigla (o SKU precisa das duas).', c_cat_nome, c_sub_nome;
  END IF;
  IF NOT v_cat_ativa OR NOT v_sub_ativa THEN
    RAISE EXCEPTION 'resguardos_mudelar: «%» ou «%» está desativada.', c_cat_nome, c_sub_nome;
  END IF;

  -- quem fica em created_by: o membro ativo mais antigo da Mudelar (como 20270118400000)
  SELECT m.user_id INTO v_criador
  FROM anew_memberships m JOIN anew_users u ON u.id = m.user_id AND u.deleted_at IS NULL
  WHERE m.organization_id = c_org AND m.status = 'active' AND m.end_date IS NULL AND coalesce(m.role_is_client, false) = false
  ORDER BY m.created_at, m.user_id LIMIT 1;
  IF v_criador IS NULL THEN RAISE EXCEPTION 'resguardos_mudelar: a Mudelar não tem um membro ativo para created_by.'; END IF;

  SELECT count(*), (array_agg(b.id ORDER BY b.created_at, b.id))[1], (array_agg(coalesce(b.is_active, true) ORDER BY b.created_at, b.id))[1]
    INTO v_n, v_marca, v_ativa
  FROM brands b
  WHERE b.organization_id = c_org AND b.deleted_at IS NULL AND public.fn_cat_chave_opcao(b.name) = public.fn_cat_chave_opcao(c_marca_nome);
  IF v_n <> 1 THEN RAISE EXCEPTION 'resguardos_mudelar: a Mudelar tem % marcas «%» (tem de ter uma).', v_n, c_marca_nome; END IF;
  IF NOT v_ativa THEN RAISE EXCEPTION 'resguardos_mudelar: a marca «%» está desativada.', c_marca_nome; END IF;

  -- o fornecedor Anlorbel que já existe (não se cria: o do Excel é este, com o nome estragado)
  SELECT count(*), (array_agg(s.id ORDER BY s.created_at, s.id))[1], (array_agg(s.name ORDER BY s.created_at, s.id))[1],
         (array_agg(coalesce(s.is_active, true) ORDER BY s.created_at, s.id))[1]
    INTO v_n, v_sup, v_sup_nome, v_ativa
  FROM suppliers s
  WHERE s.organization_id = c_org AND s.deleted_at IS NULL AND public.fn_cat_chave_opcao(s.name) = public.fn_cat_chave_opcao(c_forn_nome);
  IF v_n <> 1 THEN RAISE EXCEPTION 'resguardos_mudelar: a Mudelar tem % fornecedores «%» (tem de ter um).', v_n, c_forn_nome; END IF;
  IF NOT v_ativa THEN RAISE EXCEPTION 'resguardos_mudelar: o fornecedor «%» está desativado.', c_forn_nome; END IF;

  -- atributos cor (lista) e medida (cm), pelo código; o grupo da Cor tem de ser da Mudelar
  SELECT count(*) FILTER (WHERE a.code::text = 'cor' AND NOT a.is_measurement), count(*) FILTER (WHERE a.code::text = 'medida' AND a.is_measurement),
         (array_agg(a.id) FILTER (WHERE a.code::text = 'cor' AND NOT a.is_measurement))[1],
         (array_agg(a.id) FILTER (WHERE a.code::text = 'medida' AND a.is_measurement))[1],
         (array_agg(a.unit::text) FILTER (WHERE a.code::text = 'medida' AND a.is_measurement))[1]
    INTO v_n, v_m, v_a_cor, v_a_med, v_med_unit
  FROM product_attributes a WHERE a.organization_id = c_org AND a.deleted_at IS NULL;
  IF v_n <> 1 OR v_m <> 1 THEN
    RAISE EXCEPTION 'resguardos_mudelar: a Mudelar tem de ter um atributo cor de lista e uma medida (is_measurement).';
  END IF;
  IF coalesce(lower(v_med_unit), 'cm') <> 'cm' THEN
    RAISE EXCEPTION 'resguardos_mudelar: a Medida da Mudelar está em «%»; as medidas do Excel são em cm.', v_med_unit;
  END IF;
  v_g_cor := public.fn_cat_grupo_do_atributo(v_a_cor, c_org);
  IF NOT EXISTS (SELECT 1 FROM attribute_option_groups g WHERE g.id = v_g_cor AND g.organization_id = c_org) THEN
    RAISE EXCEPTION 'resguardos_mudelar: as opções da Cor em uso na Mudelar não são de um grupo da Mudelar.';
  END IF;
  -- Largura e Acabamento: os que já existirem (pelo código ou pelo nome), de lista e com grupo da Mudelar
  SELECT count(*), (array_agg(a.id))[1] INTO v_n, v_a_larg FROM product_attributes a
  WHERE a.organization_id = c_org AND a.deleted_at IS NULL
    AND (a.code::text = 'largura' OR public.fn_cat_chave_opcao(a.label::text) = public.fn_cat_chave_opcao(c_larg_nome));
  IF v_n > 1 THEN RAISE EXCEPTION 'resguardos_mudelar: a Mudelar tem % atributos «%».', v_n, c_larg_nome; END IF;
  SELECT count(*), (array_agg(a.id))[1] INTO v_n, v_a_acab FROM product_attributes a
  WHERE a.organization_id = c_org AND a.deleted_at IS NULL
    AND (a.code::text = 'acabamento' OR public.fn_cat_chave_opcao(a.label::text) = public.fn_cat_chave_opcao(c_acab_nome));
  IF v_n > 1 THEN RAISE EXCEPTION 'resguardos_mudelar: a Mudelar tem % atributos «%».', v_n, c_acab_nome; END IF;
  FOR r IN SELECT a.id, a.label::text AS label, a.is_measurement, coalesce(a.sku_entra, false) AS entra,
                  public.fn_cat_grupo_do_atributo(a.id, c_org) AS grupo
           FROM product_attributes a WHERE a.id IN (v_a_larg, v_a_acab) LOOP
    IF r.is_measurement OR NOT r.entra OR NOT EXISTS (SELECT 1 FROM attribute_option_groups g WHERE g.id = r.grupo AND g.organization_id = c_org) THEN
      RAISE EXCEPTION 'resguardos_mudelar: o atributo «%» da Mudelar não é de lista, não entra no SKU ou não tem grupo da Mudelar.', r.label;
    END IF;
  END LOOP;
  v_g_larg := CASE WHEN v_a_larg IS NOT NULL THEN public.fn_cat_grupo_do_atributo(v_a_larg, c_org) END;
  v_g_acab := CASE WHEN v_a_acab IS NOT NULL THEN public.fn_cat_grupo_do_atributo(v_a_acab, c_org) END;

  -- amostra de SKUs de outras categorias, para conferir que ficam iguais
  CREATE TEMP TABLE _rsg_amostra ON COMMIT DROP AS
  SELECT x.id, x.sku FROM (
    SELECT p.id, p.sku, row_number() OVER (PARTITION BY p.subcategory_id ORDER BY p.sku, p.id) AS n
    FROM products p
    WHERE p.organization_id = c_org AND NOT p.is_deleted AND p.subcategory_id IS DISTINCT FROM v_sub) x
  WHERE x.n <= 3;

  -- ─── Locks (as chaves das funções de gestão do Catálogo) ─────────────────────
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_guardar_atributo:' || c_org::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_marcas:' || c_org::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_categorias_produto:' || c_org::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_sku_config:' || c_org::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_modelos:' || c_org::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_modelos:' || c_org::text || ':' || v_sub::text, 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_sigla_opc:' || v_g_cor::text, 0));
  IF v_g_larg IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended('cat_sigla_opc:' || v_g_larg::text, 0)); END IF;
  IF v_g_acab IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended('cat_sigla_opc:' || v_g_acab::text, 0)); END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('cat_fornecedores:' || c_org::text, 0));

  PERFORM set_config('app.audit_source', c_fonte, true);
  PERFORM set_config('app.audit_user_id', v_criador::text, true);

  -- ─── 1. Cores: as opções que a Mudelar já tem (criadas se faltarem, com sigla livre) ─────
  FOR r IN SELECT c.nome_excel, c.nome_mudelar FROM _rsg_cores c
           WHERE EXISTS (SELECT 1 FROM _rsg_linhas l WHERE l.cor = c.nome_excel) ORDER BY c.ordem LOOP
    SELECT count(*), (array_agg(v.id ORDER BY v.id))[1], (array_agg(v.is_active ORDER BY v.id))[1] INTO v_n, v_opc, v_ativa
    FROM attribute_option_group_values v
    WHERE v.group_id = v_g_cor AND public.fn_cat_chave_opcao(v.value_text::text) = public.fn_cat_chave_opcao(r.nome_mudelar);
    IF v_n > 1 THEN RAISE EXCEPTION 'resguardos_mudelar: há % opções «%» na Cor da Mudelar.', v_n, r.nome_mudelar; END IF;
    IF v_n = 1 AND NOT v_ativa THEN RAISE EXCEPTION 'resguardos_mudelar: a opção «%» da Cor está desativada.', r.nome_mudelar; END IF;
    IF v_n = 0 THEN
      v_txt := public.fn_cat_sigla_opcao_livre(v_g_cor, r.nome_mudelar, NULL);
      IF v_txt IS NULL THEN RAISE EXCEPTION 'resguardos_mudelar: sem sigla livre para a cor «%».', r.nome_mudelar; END IF;
      INSERT INTO attribute_option_group_values (group_id, value_text, display_name, hex_color, sort_order, is_active, sigla)
      VALUES (v_g_cor, r.nome_mudelar, r.nome_mudelar, NULL,
              coalesce((SELECT max(v.sort_order) FROM attribute_option_group_values v WHERE v.group_id = v_g_cor), 0) + 1, true, v_txt)
      RETURNING id INTO v_opc;
      v_cores_criadas := v_cores_criadas || r.nome_mudelar || ' (' || v_txt || '); ';
    END IF;
    UPDATE _rsg_cores c SET opcao_id = v_opc WHERE c.nome_excel = r.nome_excel;
  END LOOP;
  UPDATE _rsg_cores c SET valor = v.value_text::text, sigla = v.sigla FROM attribute_option_group_values v WHERE v.id = c.opcao_id;
  IF EXISTS (SELECT 1 FROM _rsg_cores c WHERE c.opcao_id IS NOT NULL AND c.sigla IS NULL) THEN
    RAISE EXCEPTION 'resguardos_mudelar: uma das cores da Mudelar não tem sigla.';
  END IF;

  -- ─── 2. Largura (lista): o atributo (criado se faltar) e as opções ───────────
  IF v_a_larg IS NULL OR v_a_acab IS NULL THEN
    SELECT count(*) INTO v_n FROM product_attributes pa WHERE pa.organization_id = c_org AND pa.deleted_at IS NULL;
    IF v_n + 2 > c_max_atributos THEN RAISE EXCEPTION 'resguardos_mudelar: a Mudelar passaria o máximo de atributos (%).', c_max_atributos; END IF;
  END IF;
  -- como cat_guardar_atributo: lista, grupo da organização, sku_entra; o gatilho trg_cat_sku_ordem põe a sku_ordem no fim
  FOR r IN SELECT x.papel, x.nome, x.codigo FROM (VALUES (1, 'largura', c_larg_nome, 'largura'), (2, 'acabamento', c_acab_nome, 'acabamento'))
                                              AS x(o, papel, nome, codigo)
           WHERE (x.papel = 'largura' AND v_a_larg IS NULL) OR (x.papel = 'acabamento' AND v_a_acab IS NULL) ORDER BY x.o LOOP
    SELECT coalesce(max(pa.sort_order), 0) + 1 INTO v_ordem FROM product_attributes pa WHERE pa.organization_id = c_org AND pa.deleted_at IS NULL;
    v_code := r.codigo; v_i := 1;
    WHILE EXISTS (SELECT 1 FROM product_attributes pa WHERE pa.organization_id = c_org AND pa.code = v_code) LOOP
      v_i := v_i + 1;
      v_code := r.codigo || '_' || v_i::text;
    END LOOP;
    INSERT INTO product_attributes (organization_id, code, label, type, value_type, has_hex_color, is_measurement,
                                    measurement_type, unit, pricing_type, valorization_type, is_variant_option,
                                    is_variant_attribute, sort_order, created_by, sku_entra)
    VALUES (c_org, v_code, r.nome, 'select'::public.attribute_type, 'list', false, false,
            NULL, NULL, 'none', 'none', false, false, v_ordem, v_criador, true)
    RETURNING id INTO v_opc;
    INSERT INTO attribute_option_groups (attribute_id, organization_id, name, sort_order, is_active, created_by)
    VALUES (v_opc, c_org, r.nome, v_ordem, true, v_criador);
    IF r.papel = 'largura' THEN
      v_a_larg := v_opc; v_larg_criado := true; v_g_larg := public.fn_cat_grupo_do_atributo(v_opc, c_org);
      PERFORM pg_advisory_xact_lock(hashtextextended('cat_sigla_opc:' || v_g_larg::text, 0));
    ELSE
      v_a_acab := v_opc; v_acab_criado := true; v_g_acab := public.fn_cat_grupo_do_atributo(v_opc, c_org);
      PERFORM pg_advisory_xact_lock(hashtextextended('cat_sigla_opc:' || v_g_acab::text, 0));
    END IF;
  END LOOP;
  IF v_g_larg IS NULL OR v_g_acab IS NULL THEN
    RAISE EXCEPTION 'resguardos_mudelar: a Largura ou o Acabamento ficaram sem grupo de opções.';
  END IF;

  -- as opções de Largura que já existem (pelo texto, sem acentos nem maiúsculas)
  UPDATE _rsg_larguras x SET opcao_id = v.id, sigla = v.sigla, como = 'existente'
  FROM attribute_option_group_values v
  WHERE v.group_id = v_g_larg AND public.fn_cat_chave_opcao(v.value_text::text) = public.fn_cat_chave_opcao(x.valor);
  SELECT string_agg(x.valor, ', ') INTO v_txt FROM _rsg_larguras x
  WHERE (SELECT count(*) FROM attribute_option_group_values v
         WHERE v.group_id = v_g_larg AND public.fn_cat_chave_opcao(v.value_text::text) = public.fn_cat_chave_opcao(x.valor)) > 1
     OR (x.opcao_id IS NOT NULL AND (x.sigla IS NULL OR NOT (SELECT v.is_active FROM attribute_option_group_values v WHERE v.id = x.opcao_id)));
  IF v_txt IS NOT NULL THEN
    RAISE EXCEPTION 'resguardos_mudelar: opções de Largura ambíguas, desativadas ou sem sigla: %.', v_txt;
  END IF;
  -- as novas: primeiro as que levam a sigla completa (exata), depois as outras, pela ordem
  FOR r IN SELECT x.valor, x.sigla_completa, x.sigla_curta, x.sigla_decimas, x.sigla_meio, (x.sigla_completa ~ '^[A-Z0-9]{1,6}$') AS completa_cabe
           FROM _rsg_larguras x WHERE x.opcao_id IS NULL
           ORDER BY (x.sigla_completa ~ '^[A-Z0-9]{1,6}$') DESC, x.ordem LOOP
    v_txt := NULL; v_code := NULL;
    IF r.completa_cabe AND NOT EXISTS (SELECT 1 FROM attribute_option_group_values v WHERE v.group_id = v_g_larg AND v.sigla = r.sigla_completa) THEN
      v_txt := r.sigla_completa; v_code := 'completa';
    ELSIF r.sigla_curta ~ '^[A-Z0-9]{1,6}$'
          AND NOT EXISTS (SELECT 1 FROM attribute_option_group_values v WHERE v.group_id = v_g_larg AND v.sigla = r.sigla_curta) THEN
      v_txt := r.sigla_curta; v_code := 'sem décimas';
    ELSIF replace(r.sigla_curta, 'A', '') ~ '^[A-Z0-9]{1,6}$'
          AND NOT EXISTS (SELECT 1 FROM attribute_option_group_values v WHERE v.group_id = v_g_larg AND v.sigla = replace(r.sigla_curta, 'A', '')) THEN
      v_txt := replace(r.sigla_curta, 'A', ''); v_code := 'só algarismos';
    ELSIF r.sigla_decimas ~ '^[A-Z0-9]{1,6}$'
          AND NOT EXISTS (SELECT 1 FROM attribute_option_group_values v WHERE v.group_id = v_g_larg AND v.sigla = r.sigla_decimas) THEN
      v_txt := r.sigla_decimas; v_code := 'décimas';
    ELSIF r.sigla_meio ~ '^[A-Z0-9]{1,6}$'
          AND NOT EXISTS (SELECT 1 FROM attribute_option_group_values v WHERE v.group_id = v_g_larg AND v.sigla = r.sigla_meio) THEN
      v_txt := r.sigla_meio; v_code := 'décima do início';
    ELSE
      RAISE EXCEPTION 'resguardos_mudelar: nenhuma sigla legível livre para a Largura «%» (completa %, %, %, %, % ocupadas ou longas).',
        r.valor, r.sigla_completa, r.sigla_curta, replace(r.sigla_curta, 'A', ''), r.sigla_decimas, r.sigla_meio;
    END IF;
    IF v_txt IS NULL THEN RAISE EXCEPTION 'resguardos_mudelar: sem sigla livre para a Largura «%».', r.valor; END IF;
    UPDATE _rsg_larguras x SET sigla = v_txt, como = v_code WHERE x.valor = r.valor;
    INSERT INTO attribute_option_group_values (group_id, value_text, display_name, hex_color, sort_order, is_active, sigla)
    VALUES (v_g_larg, r.valor, r.valor, NULL, 0, true, v_txt)
    RETURNING id INTO v_opc;
    UPDATE _rsg_larguras x SET opcao_id = v_opc WHERE x.valor = r.valor;
  END LOOP;
  -- a ordem das novas no ecrã: depois das que já havia, por valor
  UPDATE attribute_option_group_values v
  SET sort_order = y.base + y.pos
  FROM (SELECT x.opcao_id, row_number() OVER (ORDER BY x.ordem) AS pos,
               (SELECT coalesce(max(v2.sort_order), 0) FROM attribute_option_group_values v2
                WHERE v2.group_id = v_g_larg AND NOT EXISTS (SELECT 1 FROM _rsg_larguras x2 WHERE x2.opcao_id = v2.id AND x2.como <> 'existente')) AS base
        FROM _rsg_larguras x WHERE x.como <> 'existente') y
  WHERE v.id = y.opcao_id;
  SELECT string_agg(x.como || ' ' || x.n, ', ' ORDER BY x.como) INTO v_siglas
  FROM (SELECT x.como, count(*) AS n FROM _rsg_larguras x GROUP BY x.como) x;

  -- ─── 3. Acabamento: as opções Transparente (TR) e Frost Plus (FP) ────────────
  FOR r IN SELECT x.nome, x.sigla FROM (VALUES (1, c_transp, 'TR'), (2, c_frost, 'FP')) AS x(o, nome, sigla) ORDER BY x.o LOOP
    SELECT count(*), (array_agg(v.id))[1], (array_agg(v.is_active))[1] INTO v_n, v_opc, v_ativa
    FROM attribute_option_group_values v
    WHERE v.group_id = v_g_acab AND public.fn_cat_chave_opcao(v.value_text::text) = public.fn_cat_chave_opcao(r.nome);
    IF v_n > 1 THEN RAISE EXCEPTION 'resguardos_mudelar: há % opções «%» no Acabamento.', v_n, r.nome; END IF;
    IF v_n = 1 AND NOT v_ativa THEN RAISE EXCEPTION 'resguardos_mudelar: a opção «%» do Acabamento está desativada.', r.nome; END IF;
    IF v_n = 0 THEN
      v_txt := CASE WHEN NOT EXISTS (SELECT 1 FROM attribute_option_group_values v WHERE v.group_id = v_g_acab AND v.sigla = r.sigla)
                    THEN r.sigla ELSE public.fn_cat_sigla_opcao_livre(v_g_acab, r.nome, NULL) END;
      INSERT INTO attribute_option_group_values (group_id, value_text, display_name, hex_color, sort_order, is_active, sigla)
      VALUES (v_g_acab, r.nome, r.nome, NULL,
              coalesce((SELECT max(v.sort_order) FROM attribute_option_group_values v WHERE v.group_id = v_g_acab), 0) + 1, true, v_txt)
      RETURNING id INTO v_opc;
    END IF;
    IF r.nome = c_frost THEN v_frost := v_opc; END IF;
  END LOOP;
  SELECT v.value_text::text, v.sigla INTO v_frost_valor, v_frost_sigla FROM attribute_option_group_values v WHERE v.id = v_frost;
  IF v_frost_sigla IS NULL THEN RAISE EXCEPTION 'resguardos_mudelar: a opção «%» do Acabamento não tem sigla.', c_frost; END IF;

  -- ─── 4. Os modelos na subcategoria ────────────────────────────────────────────
  UPDATE _rsg_modelos m SET modelo_id = pm.id
  FROM product_models pm
  WHERE pm.organization_id = c_org AND pm.subcategory_id = v_sub AND pm.numero = m.numero AND pm.deleted_at IS NULL
    AND public.fn_cat_chave_opcao(pm.name) = public.fn_cat_chave_opcao(m.nome);
  IF EXISTS (SELECT 1 FROM _rsg_modelos m JOIN product_models pm ON pm.id = m.modelo_id WHERE NOT pm.is_active) THEN
    RAISE EXCEPTION 'resguardos_mudelar: há modelos destes já existentes e desativados.';
  END IF;
  SELECT count(*) FILTER (WHERE pm.is_active), count(*) INTO v_n, v_m
  FROM product_models pm WHERE pm.organization_id = c_org AND pm.deleted_at IS NULL;
  SELECT count(*) INTO v_k FROM _rsg_modelos m WHERE m.modelo_id IS NULL;
  IF v_n + v_k > c_max_modelos_ativos OR v_m + v_k > c_max_modelos_vivos THEN
    RAISE EXCEPTION 'resguardos_mudelar: a Mudelar passaria o teto de modelos (% ativos, % vivos, % novos).', v_n, v_m, v_k;
  END IF;
  INSERT INTO product_models (organization_id, subcategory_id, name, numero, is_active, created_by)
  SELECT c_org, v_sub, m.nome, m.numero, true, v_criador FROM _rsg_modelos m WHERE m.modelo_id IS NULL ORDER BY m.numero;
  UPDATE _rsg_modelos m SET modelo_id = pm.id
  FROM product_models pm
  WHERE m.modelo_id IS NULL AND pm.organization_id = c_org AND pm.subcategory_id = v_sub AND pm.numero = m.numero
    AND pm.deleted_at IS NULL AND pm.name = m.nome;
  IF EXISTS (SELECT 1 FROM _rsg_modelos m WHERE m.modelo_id IS NULL) THEN
    RAISE EXCEPTION 'resguardos_mudelar: há modelos que não ficaram gravados.';
  END IF;

  -- ─── 5. Unidade e as Medidas 2D (como cat_guardar_produto_atributos as grava) ─
  v_uom := public.fn_cat_unidade(c_org, c_unidade);
  IF v_uom IS NULL THEN RAISE EXCEPTION 'resguardos_mudelar: sem unidade «%».', c_unidade; END IF;
  UPDATE _rsg_medidas d SET vjson = jsonb_build_object('tipo', '2D',
                                                        'largura', public.fn_cat_dimensao_medida(d.largura, 'A largura'),
                                                        'comprimento', public.fn_cat_dimensao_medida(d.comprimento, 'O comprimento'),
                                                        'espessura', NULL, 'unidade', 'cm');
  UPDATE _rsg_medidas d SET vtext = public.fn_cat_dimensao_texto(d.vjson -> 'largura') || ' × ' || public.fn_cat_dimensao_texto(d.vjson -> 'comprimento') || ' cm',
                            seg = public.fn_cat_sku_medida(d.vjson);
  IF EXISTS (SELECT 1 FROM _rsg_medidas d WHERE d.seg IS NULL OR d.vtext IS NULL OR public.fn_cat_medida_ler(d.vjson, 'cm') IS NULL) THEN
    RAISE EXCEPTION 'resguardos_mudelar: há medidas inválidas para o SKU.';
  END IF;

  -- ─── 6. As linhas a gravar, com o SKU final (a regra de fn_cat_sku_partes, set-based) ──────────
  CREATE TEMP TABLE _rsg_attr (id uuid PRIMARY KEY, papel text NOT NULL, sku_ordem integer, ordem integer NOT NULL, nome text NOT NULL,
                               entra boolean NOT NULL) ON COMMIT DROP;
  INSERT INTO _rsg_attr (id, papel, sku_ordem, ordem, nome, entra)
  SELECT a.id, x.papel, a.sku_ordem, coalesce(a.sort_order, 0), a.label::text, coalesce(a.sku_entra, false)
  FROM (VALUES ('cor', v_a_cor), ('medida', v_a_med), ('largura', v_a_larg), ('acabamento', v_a_acab)) AS x(papel, id)
  JOIN product_attributes a ON a.id = x.id;
  IF (SELECT count(*) FROM _rsg_attr) <> 4 THEN RAISE EXCEPTION 'resguardos_mudelar: os 4 atributos não são distintos.'; END IF;
  v_prefixo := concat_ws('-', v_cat_sigla, v_sub_sigla);

  CREATE TEMP TABLE _rsg ON COMMIT DROP AS
  SELECT gen_random_uuid() AS id, l.linha, l.modelo, m.modelo_id, l.nome, l.status, l.custo, l.pvp, l.cod_forn, l.frost,
         c.valor AS cor_valor, c.opcao_id AS cor_opcao, c.sigla AS cor_sigla,
         x.valor AS larg_valor, x.opcao_id AS larg_opcao, x.sigla AS larg_sigla,
         d.vjson AS med_json, d.vtext AS med_texto, d.seg AS med_seg,
         (SELECT count(*) FROM (VALUES (c.valor), (x.valor), (d.vtext), (CASE WHEN l.frost THEN 'x' END)) AS t(v) WHERE t.v IS NOT NULL) AS n_valores,
         NULL::text AS sku
  FROM _rsg_linhas l
  JOIN _rsg_modelos m ON m.numero = l.modelo
  LEFT JOIN _rsg_cores c ON c.nome_excel = l.cor
  LEFT JOIN _rsg_larguras x ON x.valor = l.largura
  LEFT JOIN _rsg_medidas d ON d.id = l.medida;
  SELECT count(*) INTO v_n FROM _rsg;
  IF v_n <> c_total THEN RAISE EXCEPTION 'resguardos_mudelar: % linhas a gravar em vez de %.', v_n, c_total; END IF;
  SELECT sum(b.n_valores) INTO v_n FROM _rsg b;
  IF v_n <> c_n_valores THEN RAISE EXCEPTION 'resguardos_mudelar: % valores de atributos a gravar em vez de %.', v_n, c_n_valores; END IF;

  -- CAT-SUB-NNNN-<um segmento por atributo que entra, por sku_ordem NULLS LAST, sort_order, nome, id>
  UPDATE _rsg b SET sku = concat_ws('-', v_prefixo, lpad(b.modelo::text, 4, '0'),
    (SELECT nullif(string_agg(s.seg, '-' ORDER BY a.sku_ordem NULLS LAST, a.ordem, a.nome, a.id) FILTER (WHERE a.entra AND s.seg IS NOT NULL), '')
     FROM (VALUES ('cor', b.cor_sigla), ('medida', b.med_seg), ('largura', b.larg_sigla),
                  ('acabamento', CASE WHEN b.frost THEN v_frost_sigla END)) AS s(papel, seg)
     JOIN _rsg_attr a ON a.papel = s.papel));

  -- SKU repetido entre as linhas: para e diz quais
  SELECT string_agg(x.sku || ' ×' || x.n || ' (' || x.nomes || ')', '; ') INTO v_txt
  FROM (SELECT b.sku, count(*) AS n, string_agg(b.nome, ' | ' ORDER BY b.linha) AS nomes FROM _rsg b
        GROUP BY b.sku HAVING count(*) > 1 ORDER BY b.sku LIMIT 10) x;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'resguardos_mudelar: SKUs repetidos: %', v_txt; END IF;
  -- já usado por outro produto da Mudelar (vivo ou apagado: products_sku_organization_id_key cobre os dois)
  SELECT string_agg(b.sku || ' (' || p.name || ')', '; ') INTO v_txt
  FROM (SELECT b2.sku FROM _rsg b2 JOIN products p2 ON p2.organization_id = c_org AND p2.sku = b2.sku ORDER BY b2.sku LIMIT 10) b
  JOIN products p ON p.organization_id = c_org AND p.sku = b.sku;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'resguardos_mudelar: SKUs já usados noutros produtos da Mudelar: %', v_txt; END IF;
  v_regex := '^' || v_prefixo || '-[0-9]{4}(-[A-Z0-9]+){0,4}$';
  IF EXISTS (SELECT 1 FROM _rsg b WHERE b.sku !~ v_regex) THEN
    RAISE EXCEPTION 'resguardos_mudelar: SKU fora do formato (ex.: %).', (SELECT b.sku FROM _rsg b WHERE b.sku !~ v_regex LIMIT 1);
  END IF;

  -- ─── 7. Gravar (auditoria por linha desligada: fica uma linha consolidada no fim) ───────────────
  PERFORM set_config('app.audit_bypass', 'on', true);

  -- como cat_guardar_produto: vendável (produto), comprável, sem variantes, gere stock; estado = o do Excel; o gatilho
  -- trg_cat_produto_tabelas preenche marca_livre, unidade e catalogo_categoria_id a partir dos ids
  INSERT INTO products (id, organization_id, sku, name, status, is_active, is_sellable, is_purchasable, has_variants, is_deleted,
                        manages_stock, created_by, tipo_catalogo, category_id, subcategory_id, model_id, brand_id, uom_id,
                        supplier_id, fornecedor_livre, sku_gerado)
  SELECT b.id, c_org, b.sku, b.nome, b.status::product_status, true, true, true, false, false,
         true, v_criador, 'produto', v_cat, v_sub, b.modelo_id, v_marca, v_uom,
         v_sup, public.fn_cat_limpar_nome(v_sup_nome), true
  FROM _rsg b ORDER BY b.linha;

  INSERT INTO product_organizations (product_id, organization_id, created_by)
  SELECT b.id, c_org, v_criador FROM _rsg b ORDER BY b.linha;

  -- custo (preco_exato a 6 casas, price a 2) e PVP, só para quem tem preço; o PVP 1 µs depois
  INSERT INTO product_prices (product_id, currency, price, preco_exato, valid_from, created_by, price_type, vat_rate)
  SELECT b.id, 'EUR'::currency_code, round(b.custo, 2), round(b.custo, 6), v_agora, v_criador, 'purchase'::price_type, c_iva
  FROM _rsg b WHERE b.custo IS NOT NULL
  UNION ALL
  SELECT b.id, 'EUR'::currency_code, round(b.pvp, 2), NULL::numeric, v_agora + interval '1 microsecond', v_criador, 'retail'::price_type, c_iva
  FROM _rsg b WHERE b.pvp IS NOT NULL;

  -- como cat_guardar_produto_atributos: opção = value_text da opção; medida = value_json 2D em cm e o texto «a × b cm»
  INSERT INTO product_attribute_values (product_id, attribute_id, value_text, value_json, unit)
  SELECT b.id, v_a_cor, b.cor_valor, NULL::jsonb, NULL::text FROM _rsg b WHERE b.cor_valor IS NOT NULL
  UNION ALL
  SELECT b.id, v_a_larg, b.larg_valor, NULL::jsonb, NULL::text FROM _rsg b WHERE b.larg_valor IS NOT NULL
  UNION ALL
  SELECT b.id, v_a_med, b.med_texto, b.med_json, 'cm' FROM _rsg b WHERE b.med_json IS NOT NULL
  UNION ALL
  SELECT b.id, v_a_acab, v_frost_valor, NULL::jsonb, NULL::text FROM _rsg b WHERE b.frost;

  -- como cat_ligar_fornecedor_produto: preferido; supplier_sku = código do fornecedor, ou o SKU se não vier; preço = custo
  INSERT INTO item_suppliers (organization_id, item_type, product_id, supplier_id, uom_id, supplier_sku, purchase_price, currency,
                              is_preferred, is_active, created_by, preco_data)
  SELECT c_org, 'product', b.id, v_sup, NULL, coalesce(b.cod_forn, b.sku), round(b.custo, 2), 'EUR', true, true, v_criador,
         (CASE WHEN b.custo IS NOT NULL THEN current_date END)
  FROM _rsg b ORDER BY b.linha;

  PERFORM set_config('app.audit_bypass', 'off', true);
  PERFORM public.fn_manual_audit_log('products', v_sub, c_org, 'INSERT',
    jsonb_build_object('importacao', 'resguardos_mudelar', 'produtos', c_total, 'modelos', c_n_modelos, 'subcategoria', v_sub,
                       'fornecedor', v_sup, 'unidade', v_uom, 'largura_criada', v_larg_criado, 'acabamento_criado', v_acab_criado,
                       'siglas_largura', v_siglas, 'cores_criadas', v_cores_criadas),
    c_fonte, v_sub);
  IF NOT EXISTS (SELECT 1 FROM entity_audit_log e WHERE e.organization_id = c_org AND e.source = c_fonte
                 AND e.table_name = 'products' AND e.created_at >= now()) THEN
    RAISE WARNING 'resguardos_mudelar: a linha consolidada da auditoria não ficou gravada (fn_manual_audit_log engole o erro).';
  END IF;

  -- ─── 8. Conferir (cada contagem é do que está ERRADO; tem de dar 0) ───────────
  -- quantos, por modelo, e os modelos
  SELECT count(*) INTO v_n FROM products p WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted;
  IF v_n <> c_total THEN RAISE EXCEPTION 'Conferir: % produtos na subcategoria em vez de %.', v_n, c_total; END IF;
  SELECT count(*), string_agg(m.nome || ' ' || coalesce(x.n, 0) || ' em vez de ' || m.esperados, '; ') INTO v_n, v_txt
  FROM _rsg_modelos m
  LEFT JOIN (SELECT p.model_id, count(*) AS n FROM products p
             WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted GROUP BY p.model_id) x ON x.model_id = m.modelo_id
  WHERE coalesce(x.n, 0) <> m.esperados;
  IF v_n > 0 THEN RAISE EXCEPTION 'Conferir: contagem por modelo errada em %: %', v_n, left(v_txt, 1500); END IF;
  SELECT count(*) INTO v_n FROM _rsg_modelos m LEFT JOIN product_models pm ON pm.id = m.modelo_id
  WHERE NOT coalesce(pm.organization_id = c_org AND pm.subcategory_id = v_sub AND pm.deleted_at IS NULL AND pm.is_active
                     AND pm.numero = m.numero AND pm.name = m.nome, false);
  SELECT count(*) INTO v_m FROM product_models pm WHERE pm.organization_id = c_org AND pm.subcategory_id = v_sub;
  IF v_n > 0 OR v_m <> c_n_modelos THEN
    RAISE EXCEPTION 'Conferir: % modelos errados; % na subcategoria em vez de %.', v_n, v_m, c_n_modelos;
  END IF;

  -- cada produto tal como a sua linha (LEFT JOIN + NOT coalesce(…, false): o que falta também conta como errado)
  SELECT count(*), string_agg(b.linha::text, ', ') INTO v_n, v_txt
  FROM _rsg b
  LEFT JOIN products p ON p.id = b.id
  LEFT JOIN product_attribute_values vc ON vc.product_id = b.id AND vc.attribute_id = v_a_cor
  LEFT JOIN product_attribute_values vl ON vl.product_id = b.id AND vl.attribute_id = v_a_larg
  LEFT JOIN product_attribute_values vm ON vm.product_id = b.id AND vm.attribute_id = v_a_med
  LEFT JOIN product_attribute_values va ON va.product_id = b.id AND va.attribute_id = v_a_acab
  LEFT JOIN product_prices pc ON pc.product_id = b.id AND pc.price_type = 'purchase'
  LEFT JOIN product_prices pv ON pv.product_id = b.id AND pv.price_type = 'retail'
  LEFT JOIN item_suppliers i ON i.product_id = b.id AND i.deleted_at IS NULL
  WHERE NOT coalesce(
        p.organization_id = c_org AND p.name = b.nome AND p.sku = b.sku AND p.sku_gerado AND p.model_id = b.modelo_id
        AND p.category_id = v_cat AND p.subcategory_id = v_sub AND p.brand_id = v_marca AND p.marca_livre = c_marca_nome
        AND p.uom_id = v_uom AND p.unidade = c_unidade AND p.status::text = b.status AND p.tipo_catalogo = 'produto'
        AND p.manages_stock AND p.is_active AND NOT p.is_deleted AND p.supplier_id = v_sup
        AND p.fornecedor_livre = public.fn_cat_limpar_nome(v_sup_nome)
        AND vc.value_text IS NOT DISTINCT FROM b.cor_valor
        AND vl.value_text IS NOT DISTINCT FROM b.larg_valor
        AND vm.value_json IS NOT DISTINCT FROM b.med_json AND vm.value_text IS NOT DISTINCT FROM b.med_texto
        AND (vm.product_id IS NULL OR (vm.unit = 'cm' AND public.fn_cat_medida_ler(vm.value_json, vm.unit) IS NOT NULL))
        AND (va.value_text IS NOT DISTINCT FROM (CASE WHEN b.frost THEN v_frost_valor END))
        AND pc.price IS NOT DISTINCT FROM round(b.custo, 2) AND pc.preco_exato IS NOT DISTINCT FROM round(b.custo, 6)
        AND (pc.product_id IS NULL OR pc.vat_rate = c_iva)
        AND pv.price IS NOT DISTINCT FROM round(b.pvp, 2) AND (pv.product_id IS NULL OR pv.vat_rate = c_iva)
        AND i.supplier_id = v_sup AND i.is_preferred AND i.is_active AND i.organization_id = c_org
        AND i.purchase_price IS NOT DISTINCT FROM round(b.custo, 2) AND i.supplier_sku = coalesce(b.cod_forn, p.sku)
        AND i.preco_data IS NOT DISTINCT FROM (CASE WHEN b.custo IS NOT NULL THEN current_date END),
        false);
  IF v_n > 0 THEN RAISE EXCEPTION 'Conferir: % produtos não ficaram como a linha do Excel (linhas %).', v_n, left(v_txt, 1000); END IF;
  -- nem linhas a mais
  SELECT (SELECT count(*) FROM product_attribute_values v JOIN _rsg b ON b.id = v.product_id),
         (SELECT count(*) FROM product_prices x JOIN _rsg b ON b.id = x.product_id)
    INTO v_n, v_m;
  IF v_n <> c_n_valores OR v_m <> 2 * c_n_com_preco THEN
    RAISE EXCEPTION 'Conferir: % valores de atributos (esperados %) e % preços (esperados %).', v_n, c_n_valores, v_m, 2 * c_n_com_preco;
  END IF;
  SELECT (SELECT count(*) FROM item_suppliers x JOIN _rsg b ON b.id = x.product_id),
         (SELECT count(*) FROM product_organizations x JOIN _rsg b ON b.id = x.product_id)
    INTO v_n, v_m;
  IF v_n <> c_total OR v_m <> c_total THEN
    RAISE EXCEPTION 'Conferir: % ligações a fornecedor e % product_organizations (esperados %).', v_n, v_m, c_total;
  END IF;

  -- o Acabamento: lista, entra no SKU, com Transparente e Frost Plus ativos e com sigla
  IF NOT EXISTS (SELECT 1 FROM product_attributes a WHERE a.id = v_a_acab AND a.organization_id = c_org AND a.deleted_at IS NULL
                 AND NOT a.is_measurement AND a.sku_entra AND a.sku_ordem IS NOT NULL)
     OR (SELECT count(*) FROM attribute_option_group_values v
         WHERE v.group_id = v_g_acab AND v.is_active AND v.sigla IS NOT NULL
           AND public.fn_cat_chave_opcao(v.value_text::text) IN (public.fn_cat_chave_opcao(c_transp), public.fn_cat_chave_opcao(c_frost))) <> 2 THEN
    RAISE EXCEPTION 'Conferir: o atributo Acabamento não ficou de lista, a entrar no SKU, com Transparente e Frost Plus.';
  END IF;
  -- as opções de Largura usadas: ativas, com sigla, no grupo da Largura, e siglas únicas no grupo
  SELECT count(*) INTO v_n FROM _rsg_larguras x LEFT JOIN attribute_option_group_values v ON v.id = x.opcao_id
  WHERE NOT coalesce(v.group_id = v_g_larg AND v.value_text::text = x.valor AND v.sigla = x.sigla AND v.is_active
                     AND v.sigla ~ '^[A-Z0-9]{1,6}$', false);
  SELECT count(*) - count(DISTINCT v.sigla) INTO v_m FROM attribute_option_group_values v WHERE v.group_id = v_g_larg AND v.sigla IS NOT NULL;
  IF v_n > 0 OR v_m > 0 THEN RAISE EXCEPTION 'Conferir: % opções de Largura erradas; % siglas repetidas no grupo.', v_n, v_m; END IF;

  -- SKUs: únicos, no formato, e iguais ao que cat_gerar_sku_produto calcula a partir do que ficou gravado (todos)
  SELECT count(*), count(DISTINCT p.sku), count(*) FILTER (WHERE p.sku !~ v_regex OR NOT p.sku_gerado) INTO v_n, v_m, v_k
  FROM products p WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted;
  IF v_m <> c_total OR v_n <> c_total THEN RAISE EXCEPTION 'Conferir: SKUs não únicos (% distintos em %).', v_m, v_n; END IF;
  IF v_k > 0 THEN RAISE EXCEPTION 'Conferir: % SKUs fora do formato % ou não gerados.', v_k, v_regex; END IF;
  SELECT count(*), string_agg(y.sku || ' ≠ ' || coalesce(y.calc, 'null'), '; ') FILTER (WHERE y.k <= 5) INTO v_n, v_txt
  FROM (SELECT x.sku, x.calc, row_number() OVER (ORDER BY x.sku) AS k FROM (
          SELECT p.sku, pt ->> 'faltas' AS faltas, (pt ->> 'prefixo') AS prefixo,
                 concat_ws('-', pt ->> 'prefixo', lpad(public.fn_cat_modelo_numero(c_org, p.subcategory_id, p.model_id)::text, 4, '0'),
                           pt ->> 'resto') AS calc
          FROM products p
          CROSS JOIN LATERAL (SELECT public.fn_cat_sku_partes(c_org, p.category_id, p.subcategory_id, (
              SELECT coalesce(jsonb_agg(jsonb_build_object(
                       'atributo', v.attribute_id, 'sigla', o.sigla,
                       'medida', (CASE WHEN a.is_measurement THEN public.fn_cat_medida_ler(v.value_json, v.unit) END))), '[]'::jsonb)
              FROM product_attribute_values v
              JOIN product_attributes a ON a.id = v.attribute_id AND a.organization_id = c_org AND a.deleted_at IS NULL
              LEFT JOIN attribute_option_group_values o
                ON NOT a.is_measurement AND o.group_id = public.fn_cat_grupo_do_atributo(a.id, c_org) AND o.value_text = v.value_text
              WHERE v.product_id = p.id)) AS pt) z
          WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND NOT p.is_deleted) x
        WHERE x.calc IS DISTINCT FROM x.sku OR x.prefixo IS NULL OR x.faltas <> '[]') y;
  IF v_n > 0 THEN RAISE EXCEPTION 'Conferir: % SKUs diferentes do recalculado pela regra do Catálogo (ex.: %).', v_n, v_txt; END IF;

  -- 20 ao acaso com cat_prever_sku_modelo, como um membro da Mudelar com products.edit (só leitura; claims locais)
  SELECT u.auth_user_id INTO v_auth
  FROM anew_memberships m JOIN anew_users u ON u.id = m.user_id AND u.deleted_at IS NULL AND u.auth_user_id IS NOT NULL
  WHERE m.organization_id = c_org AND m.status = 'active' AND m.end_date IS NULL AND NOT coalesce(m.role_is_client, false)
    AND public.has_anew_permission_in_org(u.auth_user_id, 'products.edit', c_org)
  ORDER BY m.created_at, u.id LIMIT 1;
  IF v_auth IS NULL THEN
    RAISE NOTICE 'resguardos_mudelar: sem membro da Mudelar com products.edit — a comparação com cat_prever_sku_modelo ficou por fazer (o recálculo de todos foi feito).';
  ELSE
    v_claims := current_setting('request.jwt.claims', true);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_auth, 'role', 'authenticated')::text, true);
    v_n := 0;
    FOR r IN SELECT b.id, b.sku, b.modelo_id, b.cor_opcao, b.larg_opcao, b.med_json, b.frost FROM _rsg b ORDER BY random() LIMIT c_amostra LOOP
      v_attrs := '[]'::jsonb;
      IF r.cor_opcao IS NOT NULL THEN v_attrs := v_attrs || jsonb_build_object('atributo', v_a_cor, 'opcao', r.cor_opcao); END IF;
      IF r.larg_opcao IS NOT NULL THEN v_attrs := v_attrs || jsonb_build_object('atributo', v_a_larg, 'opcao', r.larg_opcao); END IF;
      IF r.med_json IS NOT NULL THEN v_attrs := v_attrs || jsonb_build_object('atributo', v_a_med, 'medida', r.med_json); END IF;
      IF r.frost THEN v_attrs := v_attrs || jsonb_build_object('atributo', v_a_acab, 'opcao', v_frost); END IF;
      v_prev := public.cat_prever_sku_modelo(c_org, v_cat, v_sub, r.modelo_id, v_attrs, r.id);
      IF (v_prev ->> 'sku') IS DISTINCT FROM r.sku OR coalesce(v_prev -> 'faltas', '[]'::jsonb) <> '[]'::jsonb THEN
        RAISE EXCEPTION 'Conferir: cat_prever_sku_modelo dá % para o produto com o SKU %.', v_prev, r.sku;
      END IF;
      v_n := v_n + 1;
    END LOOP;
    PERFORM set_config('request.jwt.claims', coalesce(v_claims, ''), true);
    IF v_n <> c_amostra THEN RAISE EXCEPTION 'Conferir: só % de % comparados com cat_prever_sku_modelo.', v_n, c_amostra; END IF;
  END IF;

  -- nada foi escrito fora da Mudelar: nenhuma linha de outra organização tem o xmin desta transação
  v_xid := (txid_current() % 4294967296)::text;
  SELECT string_agg(x.t || ' ' || x.n, ', ') INTO v_txt FROM (
    SELECT 'products' AS t, count(*) AS n FROM products p WHERE p.xmin::text = v_xid AND p.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_prices', count(*) FROM product_prices x JOIN products p ON p.id = x.product_id
              WHERE x.xmin::text = v_xid AND p.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_attribute_values', count(*) FROM product_attribute_values x JOIN products p ON p.id = x.product_id
              WHERE x.xmin::text = v_xid AND p.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_organizations', count(*) FROM product_organizations x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'item_suppliers', count(*) FROM item_suppliers x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'suppliers', count(*) FROM suppliers x WHERE x.xmin::text = v_xid
    UNION ALL SELECT 'brands', count(*) FROM brands x WHERE x.xmin::text = v_xid
    UNION ALL SELECT 'product_categories', count(*) FROM product_categories x WHERE x.xmin::text = v_xid
    UNION ALL SELECT 'product_models', count(*) FROM product_models x WHERE x.xmin::text = v_xid
              AND (x.organization_id IS DISTINCT FROM c_org OR x.subcategory_id IS DISTINCT FROM v_sub)
    UNION ALL SELECT 'uom', count(*) FROM uom x WHERE x.xmin::text = v_xid AND x.organization_id IS DISTINCT FROM c_org
    UNION ALL SELECT 'product_attributes', count(*) FROM product_attributes x WHERE x.xmin::text = v_xid
              AND (x.organization_id IS DISTINCT FROM c_org OR x.id NOT IN (v_a_larg, v_a_acab))
    UNION ALL SELECT 'attribute_option_groups', count(*) FROM attribute_option_groups x WHERE x.xmin::text = v_xid
              AND (x.organization_id IS DISTINCT FROM c_org OR x.id NOT IN (v_g_larg, v_g_acab))
    UNION ALL SELECT 'attribute_option_group_values', count(*) FROM attribute_option_group_values v
              WHERE v.xmin::text = v_xid AND v.group_id NOT IN (v_g_cor, v_g_larg, v_g_acab)) x
  WHERE x.n > 0;
  IF v_txt IS NOT NULL THEN RAISE EXCEPTION 'Conferir: foram escritas linhas fora do âmbito: %', v_txt; END IF;
  -- e a própria importação escreveu na transação de topo (senão a verificação acima não provava nada)
  IF NOT EXISTS (SELECT 1 FROM products p WHERE p.organization_id = c_org AND p.subcategory_id = v_sub AND p.xmin::text = v_xid) THEN
    RAISE EXCEPTION 'Conferir: os produtos importados não têm o xmin desta transação: a verificação de «nada fora da Mudelar» não vale.';
  END IF;
  -- nenhum outro produto da Mudelar escrito, nem opções de Cor mudadas (só as criadas aqui), e a amostra intacta
  SELECT count(*) INTO v_n FROM products p
  WHERE p.organization_id = c_org AND p.xmin::text = v_xid AND NOT EXISTS (SELECT 1 FROM _rsg b WHERE b.id = p.id);
  SELECT count(*) INTO v_m FROM attribute_option_group_values v
  WHERE v.group_id = v_g_cor AND v.xmin::text = v_xid AND position(v.value_text::text || ' (' IN v_cores_criadas) = 0;
  SELECT count(*) INTO v_k FROM _rsg_amostra a LEFT JOIN products p ON p.id = a.id
  WHERE NOT coalesce(p.sku = a.sku AND NOT p.is_deleted AND p.organization_id = c_org, false);
  IF v_n > 0 OR v_m > 0 OR v_k > 0 THEN
    RAISE EXCEPTION 'Conferir: escritos % outros produtos da Mudelar, % opções de Cor que já existiam; % SKUs da amostra mudaram.', v_n, v_m, v_k;
  END IF;

  RAISE NOTICE 'resguardos_mudelar: % produtos em «%» › «%» (% modelos, SKU %-NNNN-…), fornecedor %. Largura % (% opções: %), Acabamento % (FP = %). Cores criadas: %. Conferido.',
    c_total, c_cat_nome, c_sub_nome, c_n_modelos, v_prefixo, v_sup_nome,
    (CASE WHEN v_larg_criado THEN 'criada' ELSE 'já existia' END), c_n_larguras, v_siglas,
    (CASE WHEN v_acab_criado THEN 'criado' ELSE 'já existia' END), v_frost_sigla, coalesce(nullif(v_cores_criadas, ''), 'nenhuma');
END $mig$;

RESET statement_timeout;
RESET lock_timeout;
